world/props-core.js.GB:
class GB {
  constructor() { this.p = []; this.n = []; this.uv = []; this.c = []; this.idx = []; }
  v(x, y, z, nx, ny, nz, u = 0, v = 0, c = 1) { this.p.push(x, y, z); this.n.push(nx, ny, nz); this.uv.push(u, v); this.c.push(c, c, c); return this.p.length / 3 - 1; }
  // Triangles are auto-oriented so their winding agrees with the supplied vertex normals (all our shapes supply outward normals).
  tri(a, b, c) {
    const P = this.p, N = this.n;
    const ax = P[a * 3], ay = P[a * 3 + 1], az = P[a * 3 + 2];
    const e1x = P[b * 3] - ax, e1y = P[b * 3 + 1] - ay, e1z = P[b * 3 + 2] - az;
    const e2x = P[c * 3] - ax, e2y = P[c * 3 + 1] - ay, e2z = P[c * 3 + 2] - az;
    const cx = e1y * e2z - e1z * e2y, cy = e1z * e2x - e1x * e2z, cz = e1x * e2y - e1y * e2x;
    if (cx * cx + cy * cy + cz * cz < 1e-16) return;
    const s = cx * (N[a * 3] + N[b * 3] + N[c * 3]) + cy * (N[a * 3 + 1] + N[b * 3 + 1] + N[c * 3 + 1]) + cz * (N[a * 3 + 2] + N[b * 3 + 2] + N[c * 3 + 2]);
    if (s < 0) this.idx.push(a, c, b); else this.idx.push(a, b, c);
  }
  quad(a, b, c, d) { this.tri(a, b, c); this.tri(a, c, d); }
  geo() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(this.p, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(this.n, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(this.uv, 2));
    g.setAttribute('color', new THREE.Float32BufferAttribute(this.c, 3));
    g.setIndex(this.idx);
    return g;
  }
}

world/props-core.js.chamferBox:
function chamferBox(w, h, d, r) {
  const H = [w / 2, h / 2, d / 2];
  r = Math.max(0.0005, Math.min(r, H[0] * 0.48, H[1] * 0.48, H[2] * 0.48));
  const g = new GB();
  const mk = (p, a, s) => {
    const n = [0, 0, 0]; n[a] = s;
    const o1 = (a + 1) % 3, o2 = (a + 2) % 3;
    return g.v(p[0], p[1], p[2], n[0], n[1], n[2], (p[o1] + H[o1]) / (2 * H[o1]), (p[o2] + H[o2]) / (2 * H[o2]));
  };
  for (let a = 0; a < 3; a++) for (const s of [-1, 1]) {
    const b = (a + 1) % 3, c = (a + 2) % 3, ids = [];
    for (const [sb, sc] of [[-1, -1], [1, -1], [1, 1], [-1, 1]]) { const p = [0, 0, 0]; p[a] = s * H[a]; p[b] = sb * (H[b] - r); p[c] = sc * (H[c] - r); ids.push(mk(p, a, s)); }
    g.quad(ids[0], ids[1], ids[2], ids[3]);
  }
  for (let a = 0; a < 3; a++) {
    const b = (a + 1) % 3, c = (a + 2) % 3;
    for (const sa of [-1, 1]) for (const sb of [-1, 1]) {
      const q = [];
      for (const sc of [-1, 1]) { const p = [0, 0, 0]; p[a] = sa * H[a]; p[b] = sb * (H[b] - r); p[c] = sc * (H[c] - r); q.push(mk(p, a, sa)); }
      for (const sc of [1, -1]) { const p = [0, 0, 0]; p[a] = sa * (H[a] - r); p[b] = sb * H[b]; p[c] = sc * (H[c] - r); q.push(mk(p, b, sb)); }
      g.quad(q[0], q[1], q[2], q[3]);
    }
  }
  for (const sx of [-1, 1]) for (const sy of [-1, 1]) for (const sz of [-1, 1]) {
    const s = [sx, sy, sz], ids = [];
    for (let a = 0; a < 3; a++) { const p = [0, 0, 0]; for (let k = 0; k < 3; k++) p[k] = s[k] * (k === a ? H[k] : H[k] - r); ids.push(mk(p, a, s[a])); }
    g.tri(ids[0], ids[1], ids[2]);
  }
  return g.geo();
}

world/props-core.js.roundBox:
function roundBox(w, h, d, r) {
  const H = [w / 2, h / 2, d / 2];
  r = Math.max(0.001, Math.min(r, H[0] * 0.48, H[1] * 0.48, H[2] * 0.48));
  const g = new GB();
  const I = [H[0] - r, H[1] - r, H[2] - r];
  for (let a = 0; a < 3; a++) for (const s of [-1, 1]) {
    const b = (a + 1) % 3, c = (a + 2) % 3;
    const cb = [-H[b], -I[b], I[b], H[b]], cc = [-H[c], -I[c], I[c], H[c]];
    const ids = [];
    for (let i = 0; i < 4; i++) for (let j = 0; j < 4; j++) {
      const p = [0, 0, 0]; p[a] = s * H[a]; p[b] = cb[i]; p[c] = cc[j];
      const q = [0, 0, 0], n = [0, 0, 0];
      let len = 0;
      for (let k = 0; k < 3; k++) { const inner = Math.max(-I[k], Math.min(I[k], p[k])); n[k] = p[k] - inner; q[k] = inner; len += n[k] * n[k]; }
      len = Math.sqrt(len) || 1;
      for (let k = 0; k < 3; k++) { n[k] /= len; q[k] += n[k] * r; }
      ids.push(g.v(q[0], q[1], q[2], n[0], n[1], n[2], (p[b] + H[b]) / (2 * H[b]), (p[c] + H[c]) / (2 * H[c])));
    }
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) g.quad(ids[i * 4 + j], ids[(i + 1) * 4 + j], ids[(i + 1) * 4 + j + 1], ids[i * 4 + j + 1]);
  }
  return g.geo();
}

world/props-core.js.latheGeo:
function latheGeo(profile, seg, closed = false) {
  const g = new GB();
  const strips = [[]];
  for (const p of profile) { if (p === null) strips.push([]); else strips[strips.length - 1].push(p); }
  for (const S of strips) {
    const n = S.length; if (n < 2) continue;
    const nr = [], ny = [];
    for (let i = 0; i < n; i++) {
      let a, b;
      if (closed) { a = S[(i - 1 + n) % n]; b = S[(i + 1) % n]; } else { a = S[Math.max(0, i - 1)]; b = S[Math.min(n - 1, i + 1)]; }
      let tx = b[0] - a[0], ty = b[1] - a[1]; const l = Math.hypot(tx, ty) || 1; tx /= l; ty /= l;
      nr.push(ty); ny.push(-tx);
    }
    const rings = [];
    for (let i = 0; i < n; i++) {
      const ring = [];
      for (let k = 0; k <= seg; k++) {
        const ph = (k / seg) * TAU, cs = Math.cos(ph), sn = Math.sin(ph);
        ring.push(g.v(S[i][0] * cs, S[i][1], -S[i][0] * sn, nr[i] * cs, ny[i], -nr[i] * sn, k / seg, i / (n - 1)));
      }
      rings.push(ring);
    }
    const segs = closed ? n : n - 1;
    for (let i = 0; i < segs; i++) {
      const A = rings[i], B = rings[(i + 1) % n];
      for (let k = 0; k < seg; k++) g.quad(A[k], A[k + 1], B[k + 1], B[k]);
    }
  }
  return g.geo();
}

world/props-core.js.tubeGeo:
function tubeGeo(pts, radius, radial = 8, closed = false, up = null) {
  const n = pts.length, g = new GB();
  const P = pts.map((p) => new THREE.Vector3(p[0], p[1], p[2]));
  const T = [];
  for (let i = 0; i < n; i++) {
    const a = closed ? P[(i - 1 + n) % n] : P[Math.max(0, i - 1)], b = closed ? P[(i + 1) % n] : P[Math.min(n - 1, i + 1)];
    T.push(b.clone().sub(a).normalize());
  }
  const N = new THREE.Vector3();
  if (up) N.set(up[0], up[1], up[2]).addScaledVector(T[0], -T[0].dot(N.set(up[0], up[1], up[2]))).normalize();
  if (!up || N.lengthSq() < 0.5) { const ax = Math.abs(T[0].y) < 0.9 ? new THREE.Vector3(0, 1, 0) : new THREE.Vector3(1, 0, 0); N.crossVectors(T[0], ax).normalize(); }
  const Bv = new THREE.Vector3(), rings = [];
  for (let i = 0; i < n; i++) {
    if (i > 0) N.addScaledVector(T[i], -N.dot(T[i])).normalize();
    Bv.crossVectors(T[i], N).normalize();
    const r = typeof radius === 'function' ? radius(i / (n - 1)) : radius;
    const ring = [];
    for (let k = 0; k < radial; k++) {
      const a = (k / radial) * TAU, cs = Math.cos(a), sn = Math.sin(a);
      const nx = N.x * cs + Bv.x * sn, ny = N.y * cs + Bv.y * sn, nz = N.z * cs + Bv.z * sn;
      ring.push(g.v(P[i].x + nx * r, P[i].y + ny * r, P[i].z + nz * r, nx, ny, nz, k / radial, i / (n - 1)));
    }
    rings.push(ring);
  }
  const segs = closed ? n : n - 1;
  for (let i = 0; i < segs; i++) {
    const A = rings[i], B = rings[(i + 1) % n];
    for (let k = 0; k < radial; k++) g.quad(A[k], A[(k + 1) % radial], B[(k + 1) % radial], B[k]);
  }
  return g.geo();
}

world/level.js._faceHidden:
_faceHidden(f) {
    const nu = Math.max(2, Math.ceil(f.su / 1.25)), nv = Math.max(2, Math.ceil(f.sv / 1.25));
    for (let j = 0; j <= nv; j++) {
      for (let i = 0; i <= nu; i++) {
        const uu = Math.min(f.su - 0.05, Math.max(0.05, (i / nu) * f.su));
        const vv = Math.min(f.sv - 0.05, Math.max(0.05, (j / nv) * f.sv));
        _v.copy(f.origin).addScaledVector(f.u, uu).addScaledVector(f.v, vv).addScaledVector(f.n, 0.03);
        if (!this.pointInside(_v, 0, f.block)) return false;
      }
    }
    return true;
  }

world/level.js.buildGeometry:
buildGeometry(atlasSize, filter = (b) => !b.grate) {
    const B = { pos: [], nor: [], col: [], puv: [], luv: [], fuv: [], fdat: [], fflag: [], ftan: [], idx: [] };
    const LS = this.lightSize || 1;
    const lin = new THREE.Color();
    const P = new THREE.Vector3(), Nn = new THREE.Vector3(), E = new THREE.Vector3(), Q = new THREE.Vector3();
    const faceOf = (b, k, s) => b.faces[k * 2 + (s > 0 ? 0 : 1)];
    const self = this;
    function vert(f, p, n) {
      const i = B.pos.length / 3;
      B.pos.push(p.x, p.y, p.z); B.nor.push(n.x, n.y, n.z);
      lin.copy(f.color); B.col.push(lin.r, lin.g, lin.b);
      Q.copy(p).sub(f.origin);
      const cu = Q.dot(f.u), cv = Q.dot(f.v);
      if (f.atlas) B.puv.push((f.atlas.x + f.atlas.pad + cu * f.atlas.ppm) / atlasSize, (f.atlas.y + f.atlas.pad + cv * f.atlas.ppm) / atlasSize);
      else B.puv.push(0, 0);
      if (f.light) B.luv.push((f.light.x + f.light.pad + cu * f.light.ppm) / LS, (f.light.y + f.light.pad + cv * f.light.ppm) / LS);
      else B.luv.push(-1, -1);
      B.fuv.push(cu, cv);
      B.fdat.push(f.pattern, f.atlas ? 1 : 0, f.su, f.sv);
      B.fflag.push(f.wall ? 1 : 0, f.groundedBottom ? 1 : 0, f.mural);
      B.ftan.push(f.u.x, f.u.y, f.u.z);
      return i;
    }
    // triangle with winding chosen so it faces along `n`
    const _a = new THREE.Vector3(), _b = new THREE.Vector3(), _c = new THREE.Vector3();
    function tri(i0, i1, i2, n) {
      const pp = B.pos;
      _a.set(pp[i1 * 3] - pp[i0 * 3], pp[i1 * 3 + 1] - pp[i0 * 3 + 1], pp[i1 * 3 + 2] - pp[i0 * 3 + 2]);
      _b.set(pp[i2 * 3] - pp[i0 * 3], pp[i2 * 3 + 1] - pp[i0 * 3 + 1], pp[i2 * 3 + 2] - pp[i0 * 3 + 2]);
      _c.crossVectors(_a, _b);
      if (_c.dot(n) >= 0) B.idx.push(i0, i1, i2); else B.idx.push(i0, i2, i1);
    }
    for (const b of this.blocks) {
      if ((!b.solid && !b.render) || !filter(b)) continue;
      const ax = b.axes, h = [b.half.x, b.half.y, b.half.z];
      const minH = Math.min(h[0], h[1], h[2]);
      // bevel scales with the block: chunky rounded edges on big structures, finer on crates/ramps/rails
      const bev = Math.min(b.bevel ?? Math.max(0.04, Math.min(0.13, minH * 0.14)), minH * 0.45);
      // exposed-edge test (both faces rendered and nothing solid hugging the edge)
      const edgeCache = new Map();
      const bevelled = (k1, s1, k2, s2) => {
        if (bev < 0.01) return false;
        const key = k1 < k2 ? `${k1}${s1}${k2}${s2}` : `${k2}${s2}${k1}${s1}`;
        if (edgeCache.has(key)) return edgeCache.get(key);
        let ok = faceOf(b, k1, s1) >= 0 && faceOf(b, k2, s2) >= 0;
        if (ok) {
          const k3 = 3 - k1 - k2;
          for (let t = -1; t <= 1; t += 0.25) {
            E.copy(b.center).addScaledVector(ax[k1], s1 * h[k1]).addScaledVector(ax[k2], s2 * h[k2]).addScaledVector(ax[k3], t * h[k3] * 0.98);
            Q.copy(E).addScaledVector(ax[k1], s1 * 0.04).addScaledVector(ax[k2], s2 * 0.04);
            if (self.pointInside(Q, 0, b.id)) { ok = false; break; }
          }
        }
        edgeCache.set(key, ok);
        return ok;
      };
      // --- faces (inset where the edge is bevelled)
      for (let k = 0; k < 3; k++) for (const s of [1, -1]) {
        const fid = faceOf(b, k, s);
        if (fid < 0) continue;
        const f = this.faces[fid];
        const [i, j] = [0, 1, 2].filter((a) => a !== k);
        const ip = bevelled(k, s, i, 1) ? bev : 0, im = bevelled(k, s, i, -1) ? bev : 0;
        const jp = bevelled(k, s, j, 1) ? bev : 0, jm = bevelled(k, s, j, -1) ? bev : 0;
        const cf = E.copy(b.center).addScaledVector(ax[k], s * h[k]).clone();
        const corner = (si, sj) => {
          const di = si > 0 ? h[i] - ip : -(h[i] - im), dj = sj > 0 ? h[j] - jp : -(h[j] - jm);
          return vert(f, P.copy(cf).addScaledVector(ax[i], di).addScaledVector(ax[j], dj), f.n);
        };
        const v0 = corner(-1, -1), v1 = corner(1, -1), v2 = corner(1, 1), v3 = corner(-1, 1);
        tri(v0, v1, v2, f.n); tri(v0, v2, v3, f.n);
      }
      if (bev < 0.01) continue;
      // --- edge strips
      const SEG = 2; // per half (4 segments per quarter-round)
      for (let k1 = 0; k1 < 3; k1++) for (let k2 = k1 + 1; k2 < 3; k2++) for (const s1 of [1, -1]) for (const s2 of [1, -1]) {
        if (!bevelled(k1, s1, k2, s2)) continue;
        const k3 = 3 - k1 - k2;
        const fa = this.faces[faceOf(b, k1, s1)], fb = this.faces[faceOf(b, k2, s2)];
        const nA = ax[k1].clone().multiplyScalar(s1), nB = ax[k2].clone().multiplyScalar(s2);
        const endCut = (s3) => faceOf(b, k3, s3) >= 0 && bevelled(k3, s3, k1, s1) && bevelled(k3, s3, k2, s2) ? bev : 0;
        const t0 = -h[k3] + endCut(-1), t1 = h[k3] - endCut(1);
        const base = E.copy(b.center).addScaledVector(nA, h[k1] - bev).addScaledVector(nB, h[k2] - bev).clone();
        for (const half of [0, 1]) {
          const f = half ? fb : fa;
          const rows = [];
          for (let q = 0; q <= SEG; q++) {
            const th = (Math.PI / 4) * (half + q / SEG);
            Nn.copy(nA).multiplyScalar(Math.cos(th)).addScaledVector(nB, Math.sin(th));
            const r0 = vert(f, P.copy(base).addScaledVector(ax[k3], t0).addScaledVector(Nn, bev), Nn);
            const r1 = vert(f, P.copy(base).addScaledVector(ax[k3], t1).addScaledVector(Nn, bev), Nn);
            rows.push([r0, r1, Nn.clone()]);
          }
          for (let q = 0; q < SEG; q++) {
            const [a0, a1, na] = rows[q], [b0, b1] = rows[q + 1];
            tri(a0, a1, b1, na); tri(a0, b1, b0, na);
          }
        }
      }
      // --- rounded corners (octant patches) where all three edges are bevelled
      const NC = 3;
      for (const s0 of [1, -1]) for (const s1 of [1, -1]) for (const s2 of [1, -1]) {
        const sg = [s0, s1, s2];
        if (!(bevelled(0, s0, 1, s1) && bevelled(0, s0, 2, s2) && bevelled(1, s1, 2, s2))) continue;
        const n0 = ax[0].clone().multiplyScalar(s0), n1 = ax[1].clone().multiplyScalar(s1), n2 = ax[2].clone().multiplyScalar(s2);
        const c = E.copy(b.center).addScaledVector(n0, h[0] - bev).addScaledVector(n1, h[1] - bev).addScaledVector(n2, h[2] - bev).clone();
        // map the whole patch to the most "up" face (usually the top) so its ink matches what you see from above
        let best = 0, bd = -2;
        [n0, n1, n2].forEach((nn, a) => { if (nn.y > bd) { bd = nn.y; best = a; } });
        const f = this.faces[faceOf(b, best, sg[best])];
        const ids = [];
        for (let a = 0; a <= NC; a++) { ids.push([]); for (let bb = 0; bb <= NC - a; bb++) {
          const cc = NC - a - bb;
          Nn.set(0, 0, 0).addScaledVector(n0, a).addScaledVector(n1, bb).addScaledVector(n2, cc).normalize();
          ids[a].push(vert(f, P.copy(c).addScaledVector(Nn, bev), Nn));
        } }
        const mid = n0.clone().add(n1).add(n2).normalize();
        for (let a = 0; a < NC; a++) for (let bb = 0; bb < NC - a; bb++) {
          tri(ids[a][bb], ids[a + 1][bb], ids[a][bb + 1], mid);
          if (bb < NC - a - 1) tri(ids[a + 1][bb], ids[a + 1][bb + 1], ids[a][bb + 1], mid);
        }
      }
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(B.pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(B.nor, 3));
    g.setAttribute('color', new THREE.Float32BufferAttribute(B.col, 3));
    g.setAttribute('paintUv', new THREE.Float32BufferAttribute(B.puv, 2));
    g.setAttribute('lightUv', new THREE.Float32BufferAttribute(B.luv, 2));
    g.setAttribute('faceUv', new THREE.Float32BufferAttribute(B.fuv, 2));
    g.setAttribute('faceData', new THREE.Float32BufferAttribute(B.fdat, 4));
    g.setAttribute('faceFlags', new THREE.Float32BufferAttribute(B.fflag, 3));
    g.setAttribute('faceTan', new THREE.Float32BufferAttribute(B.ftan, 3));
    g.setIndex(B.idx);
    g.computeBoundingSphere();
    this.renderTris = B.idx.length / 3;
    return g;
  }

world/environment.js._buildSea:
_buildSea() {
    this.U.uWaveTex.value = makeWaveTexture(256, 11);
    // polar grid: dense near the arena, stretching to the horizon
    const rings = [0];
    let r = 1.5;
    while (r < 6000) { rings.push(r); r = r * 1.1 + 0.5; }
    rings.push(6000);
    const S = 128;
    const pos = [], idx = [];
    pos.push(0, 0, 0);
    for (let k = 1; k < rings.length; k++) for (let s = 0; s < S; s++) { const a = (s / S) * Math.PI * 2; pos.push(Math.cos(a) * rings[k], 0, Math.sin(a) * rings[k]); }
    for (let s = 0; s < S; s++) idx.push(0, 1 + ((s + 1) % S), 1 + s);
    for (let k = 1; k < rings.length - 1; k++) {
      const a0 = 1 + (k - 1) * S, a1 = 1 + k * S;
      for (let s = 0; s < S; s++) { const s1 = (s + 1) % S; idx.push(a0 + s, a0 + s1, a1 + s1, a0 + s, a1 + s1, a1 + s); }
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    geo.setAttribute('normal', new THREE.Float32BufferAttribute(new Float32Array(pos.length).map((_, i) => (i % 3 === 1 ? 1 : 0)), 3));
    geo.setIndex(idx);
    const uniforms = { ...THREE.UniformsUtils.clone(THREE.UniformsLib.lights), ...this.U };
    this.seaMat = new THREE.ShaderMaterial({ name: 'Sea', uniforms, vertexShader: SEA_VERT, fragmentShader: SEA_FRAG, lights: true, fog: false });
    this.sea = new THREE.Mesh(geo, this.seaMat);
    this.sea.name = 'Sea';
    this.sea.position.y = WATER_Y;
    this.sea.frustumCulled = false;
    this.sea.receiveShadow = true;
    this.sea.renderOrder = -1;
    // marina: the planar reflection is rendered right before the sea draws (camera already final for this frame)
    this.sea.onBeforeRender = (renderer, scene, camera) => this._renderReflection(renderer, scene, camera);
    this.root.add(this.sea);
  }

world/environment.js._buildScenery:
_buildScenery() {
    const U = this.U;
    const staticParts = [];
    const shoreMat = patchScenery(new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.92, metalness: 0 }), U, { shore: true });
    const rnd = mulberry(42);
    const islands = [];
    const terrainParts = [];
    const addIsland = (o) => { const isl = makeIsland(o); terrainParts.push(isl.geo); islands.push({ ...o, isl }); return isl; };

    // --- city land across the bay (east / north-east) + backdrop hills ---
    const [ccx, ccz] = polar(22, 900);
    const city = addIsland({ x: ccx, z: ccz, rx: 600, rz: 360, h: 3.2, seed: 3, rot: (22 + 90) * DEG, plateau: true, R: 10, S: 56, grass: '#c5d3ac' });
    this._cityIsland = city;
